//! End-to-end gate on a real GTEx panel (hardening 6.5): nothing supplied.
//!
//! Size factors, dispersions (parametric trend), Cook's outlier replacement
//! and independent filtering all run with DESeq2 defaults, against
//! `DESeq()` + `results()` from R 4.6.2 / DESeq2 1.52.0
//! (tests/data/gtex_end_to_end, generated by
//! scripts/references/generate_gtex_end_to_end_reference.R).
//!
//! Knife-edge note (NUMERIC, measured 2026-11-18). 3,744 of 3,745 genes match
//! R to ~1e-13 in every field. GPX3 (ENSG00000211445.11, baseMean 5.6e5) does
//! not: its MAP log posterior is about -2.57e7, so one ulp is 3.7e-9, and the
//! posterior is flat enough near the optimum that late Armijo tests compare
//! values that differ by less than one ulp. Fed R's own `mu`, prior mean and
//! prior variance, Rust's line search reproduces R's path to 1e-14 for 11
//! iterations; at iteration 14 Rust accepts a step that R rejects (R instead
//! halves kappa 20 times and accepts at iteration 32). The two end points have
//! the same log posterior to working precision; the log-dispersion gap is
//! 2.6e-5 and moves lfcSE by 5.9e-6, stat by 5.0e-6 and the p-value by
//! 3.7e-6, with no significance change. The gate below allows at most one such
//! gene, bounds it, and holds every other gene to 1e-8.

use std::path::PathBuf;

use rsdeseq2::io::{read_count_matrix_tsv, read_labeled_design_matrix_tsv};
use rsdeseq2::prelude::*;

use crate::support as common;

/// A gene's dispersion "matches" R when the log gap is at most this.
const DISPERSION_MATCH_LOG_GAP: f64 = 1e-10;
/// Largest allowed log-dispersion gap for a knife-edge gene.
const KNIFE_EDGE_LOG_GAP: f64 = 1e-4;
/// Bounds for genes whose dispersion matches R.
const MATCHED_ABS: f64 = 1e-8;
const MATCHED_LOG10: f64 = 1e-8;

fn data(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/data/gtex_end_to_end")
        .join(name)
}

fn optional(text: &str) -> Option<f64> {
    (text != "NA").then(|| text.parse().unwrap())
}

struct Gap {
    abs: f64,
    log10: f64,
    missing_mismatches: usize,
}

fn compare(
    actual: &[Option<f64>],
    expected: &[Option<f64>],
    log_scale: bool,
    keep: &dyn Fn(usize) -> bool,
) -> Gap {
    let mut gap = Gap {
        abs: 0.0,
        log10: 0.0,
        missing_mismatches: 0,
    };
    for (i, (a, e)) in actual.iter().zip(expected).enumerate() {
        if !keep(i) {
            continue;
        }
        match (a, e) {
            (Some(a), Some(e)) if a.is_finite() && e.is_finite() => {
                gap.abs = gap.abs.max((a - e).abs());
                if log_scale {
                    gap.log10 = gap.log10.max(common::probability_log10_error(*a, *e));
                }
            }
            (None, None) => {}
            _ => gap.missing_mismatches += 1,
        }
    }
    gap
}

#[test]
fn log_scale_gate_rejects_underflow_and_nonfinite_values() {
    let keep = |_| true;
    let zero = [Some(0.0)];
    let tiny = [Some(1e-310)];
    assert!(compare(&zero, &tiny, true, &keep).log10.is_infinite());
    assert!(compare(&tiny, &zero, true, &keep).log10.is_infinite());
    assert_eq!(compare(&zero, &zero, true, &keep).log10, 0.0);
    assert_eq!(
        compare(&[Some(f64::NAN)], &tiny, true, &keep).missing_mismatches,
        1,
    );
}

#[test]
fn default_pipeline_matches_deseq2_end_to_end() {
    let counts = read_count_matrix_tsv(data("counts.tsv")).unwrap();
    let labeled_design = read_labeled_design_matrix_tsv(data("design_matrix.tsv")).unwrap();
    let design = labeled_design.design;
    assert_eq!(
        counts.sample_names().unwrap(),
        labeled_design.sample_names.as_slice()
    );
    let cutoff = default_cooks_cutoff(design.n_samples(), design.n_coefficients())
        .unwrap()
        .unwrap();
    let replacement = CooksReplacementOptions::new(cutoff);
    let output = DeseqBuilder::new()
        .run(&Analysis::new(&counts, &design).cooks_replacement(&replacement))
        .unwrap();
    let RunOutput::Replacement(output) = output else {
        panic!("expected a Cook's replacement fit");
    };
    let (fit, results, refit) = output.into_merged_fit().unwrap();

    let size_factors = common::read_tsv(&data("reference_size_factors.tsv"));
    assert_eq!(size_factors.len(), counts.n_samples());
    assert_eq!(fit.size_factors.len(), counts.n_samples());
    for ((expected, actual), sample) in size_factors
        .iter()
        .zip(&fit.size_factors)
        .zip(&labeled_design.sample_names)
    {
        assert_eq!(&expected["sample"], sample);
        let target = expected["size_factor"].parse::<f64>().unwrap();
        assert!(
            (actual / target - 1.0).abs() < 1e-10,
            "{sample}: size factor {actual} vs {target}"
        );
    }

    let reference = common::read_tsv(&data("reference_results.tsv"));
    assert_eq!(reference.len(), counts.n_genes());
    assert_eq!(results.rows.len(), counts.n_genes());
    assert_eq!(refit.replacement.replace.len(), counts.n_genes());
    assert!(results.independent_filtering.as_ref().unwrap().enabled);
    for ((expected, row), replaced) in reference
        .iter()
        .zip(&results.rows)
        .zip(&refit.replacement.replace)
    {
        let gene = expected["gene"].as_str();
        assert_eq!(row.gene.as_deref(), Some(gene));
        let expected_flag = expected["replaced"].parse::<u8>().unwrap();
        assert_eq!(u8::from(*replaced == Some(true)), expected_flag, "{gene}");
    }
    let column = |name: &str| -> Vec<Option<f64>> {
        reference.iter().map(|row| optional(&row[name])).collect()
    };
    let fields: [(&str, Vec<Option<f64>>, bool); 6] = [
        (
            "baseMean",
            results.rows.iter().map(|r| Some(r.base_mean)).collect(),
            false,
        ),
        (
            "log2FoldChange",
            results.rows.iter().map(|r| r.log2_fold_change).collect(),
            false,
        ),
        (
            "lfcSE",
            results.rows.iter().map(|r| r.lfc_se).collect(),
            false,
        ),
        ("stat", results.rows.iter().map(|r| r.stat).collect(), false),
        (
            "pvalue",
            results.rows.iter().map(|r| r.pvalue).collect(),
            true,
        ),
        ("padj", results.rows.iter().map(|r| r.padj).collect(), true),
    ];
    let dispersion = fit
        .dispersion
        .as_ref()
        .unwrap()
        .iter()
        .map(|v| Some(*v).filter(|v| v.is_finite()))
        .collect::<Vec<_>>();
    let reference_dispersion = column("dispersion");
    let dispersion_log_gap = |i: usize| match (dispersion[i], reference_dispersion[i]) {
        (Some(a), Some(e)) => (a.ln() - e.ln()).abs(),
        (None, None) => 0.0,
        _ => f64::INFINITY,
    };
    // Knife-edge genes: the MAP line search compares two log posteriors that
    // agree to the last ulp, so a one-ulp summation difference decides an
    // Armijo step (see the module note). Everything else must match tightly.
    let knife_edge = (0..dispersion.len())
        .filter(|&i| dispersion_log_gap(i) > DISPERSION_MATCH_LOG_GAP)
        .collect::<Vec<_>>();
    for &i in &knife_edge {
        eprintln!(
            "knife-edge dispersion: gene {} log gap {:.3e} rust {:?} R {}",
            reference[i]["gene"],
            dispersion_log_gap(i),
            dispersion[i],
            reference[i]["dispersion"]
        );
    }
    let strict = |i: usize| !knife_edge.contains(&i);
    let edge = |i: usize| knife_edge.contains(&i);
    let mut report = Vec::new();
    for (name, actual, log_scale) in &fields {
        let expected = column(name);
        let tight = compare(actual, &expected, *log_scale, &strict);
        let loose = compare(actual, &expected, *log_scale, &edge);
        eprintln!(
            "{name}: matched genes max abs {:.3e} log10 {:.3e}; knife-edge max abs {:.3e} log10 {:.3e}; missingness mismatches {}",
            tight.abs,
            tight.log10,
            loose.abs,
            loose.log10,
            tight.missing_mismatches + loose.missing_mismatches
        );
        report.push((*name, tight, loose));
    }
    if std::env::var_os("RSDESEQ2_E2E_DETAIL").is_some() {
        for &i in &knife_edge {
            eprintln!(
                "knife-edge gene: geneEst {:.17} fit {:.17} map {:.17} iter {:?}",
                fit.disp_gene_est.as_ref().unwrap()[i],
                fit.disp_fit.as_ref().unwrap()[i],
                fit.disp_map.as_ref().unwrap()[i],
                fit.disp_iter.as_ref().map(|v| v[i]),
            );
        }
    }
    let padj = &fields[5].1;
    let flips_05 = common::significance_flips(padj, &column("padj"), 0.05);
    let flips_10 = common::significance_flips(padj, &column("padj"), 0.1);
    eprintln!("significance flips: {flips_05} at 0.05, {flips_10} at 0.1");

    // Gates. Matched genes: tight bounds. Knife-edge genes: at most one, with
    // the dispersion within KNIFE_EDGE_LOG_GAP and outputs within 1e-5.
    // Everywhere: no missingness differences and no significance flips.
    assert!(
        knife_edge.len() <= 1,
        "{} genes left the dispersion match: {:?}",
        knife_edge.len(),
        knife_edge
            .iter()
            .map(|&i| &reference[i]["gene"])
            .collect::<Vec<_>>()
    );
    for &i in &knife_edge {
        assert!(dispersion_log_gap(i) <= KNIFE_EDGE_LOG_GAP);
    }
    for (name, tight, loose) in &report {
        assert_eq!(
            tight.missing_mismatches + loose.missing_mismatches,
            0,
            "{name}: missingness differs"
        );
        let (abs_bound, log_bound) = match *name {
            "pvalue" | "padj" => (MATCHED_ABS, MATCHED_LOG10),
            _ => (MATCHED_ABS, f64::INFINITY),
        };
        assert!(
            tight.abs <= abs_bound,
            "{name}: max abs {:e} > {abs_bound:e}",
            tight.abs
        );
        assert!(
            tight.log10 <= log_bound,
            "{name}: max log10 {:e} > {log_bound:e}",
            tight.log10
        );
        assert!(
            loose.abs <= 1e-5,
            "{name}: knife-edge max abs {:e} > 1e-5",
            loose.abs
        );
        assert!(
            loose.log10 <= 1e-5,
            "{name}: knife-edge max log10 {:e} > 1e-5",
            loose.log10
        );
    }
    assert_eq!((flips_05, flips_10), (0, 0), "significance calls flipped");
}
